import re

def entities(doc, scope):
    objs = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and ": Objects" in node.get("title", ""):
            for line in node.get("lines", []):
                if line.startswith("Object "):
                    parts = line.split(":", 1)
                    obj_id = parts[0].split()[-1]
                    desc = parts[1].split("(")[0].strip() if "(" in parts[1] else parts[1].strip()
                    objs.append({"id": obj_id, "description": desc})
    return objs

def recorded_end(doc, scope):
    max_t = -1.0
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and ": Motion log" in node.get("title", ""):
            for _, row in table_rows(node):
                try:
                    f = float(row["frame"])
                    if f > max_t:
                        max_t = f
                except: pass
        elif node.get("kind") == "list" and ": Events" in node.get("title", ""):
            for line in node.get("lines", []):
                m = re.search(r"Frame (\d+):", line)
                if m:
                    f = float(m.group(1))
                    if f > max_t:
                        max_t = f
    return max_t if max_t >= 0 else None

def inputs(doc, scope):
    inps = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and ": Events" in node.get("title", ""):
            lines = node.get("lines", [])
            for i, line in enumerate(lines):
                if "is in view when the video begins" in line or "enters the scene" in line:
                    m_frame = re.search(r"Frame (\d+):", line)
                    m_obj = re.search(r"Object (\d+)", line)
                    if m_frame and m_obj:
                        inps.append({
                            "id": f"entry_{m_obj.group(1)}",
                            "time": float(m_frame.group(1)),
                            "kind": "entry",
                            "entities": [m_obj.group(1)],
                            "fields": {},
                            "src": [[node["node_id"], i]]
                        })
    return inps

def outcomes(doc, scope):
    outs = []
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and ": Events" in node.get("title", ""):
            lines = node.get("lines", [])
            for i, line in enumerate(lines):
                m_coll = re.search(r"Frame (\d+): Object (\d+) collides with Object (\d+)", line)
                if m_coll:
                    outs.append({
                        "time": float(m_coll.group(1)),
                        "kind": "collision",
                        "entities": [m_coll.group(2), m_coll.group(3)],
                        "value": None,
                        "src": [[node["node_id"], i]]
                    })
                    continue
                m_exit = re.search(r"Frame (\d+): Object (\d+) exits the scene", line)
                if m_exit:
                    outs.append({
                        "time": float(m_exit.group(1)),
                        "kind": "exit",
                        "entities": [m_exit.group(2)],
                        "value": None,
                        "src": [[node["node_id"], i]]
                    })
    return outs

def params(doc, scope):
    return {"stationary_threshold": 0.1}

